/* MiniMax clapboard strike: short cut-mark glints, decorative only. */
(()=>{const role=window.ArenaCharacterModules.minimax,previous=role.drawEffect;role.drawEffect=function(c,e,env){if(e.kind!=='swing'||e.characterId!=='minimax'||e.stage!==3)return previous?.(c,e,env)??false;const u=Math.max(0,Math.min(1,env.u??1-e.life/e.max)),dir=e.dir||1;c.save();c.translate(e.x+dir*55,e.y-85);c.scale(dir,1);c.globalAlpha=(1-u)*.85;c.strokeStyle='#ffd29c';c.lineWidth=1.5;c.beginPath();c.rect(-12,-23,44,46);c.clip();for(let j=0;j<3;j++){let x=j*8+u*7;c.beginPath();c.moveTo(x,-10+j*4);c.lineTo(x+5,-16+j*4);c.moveTo(x+1,6+j*3);c.lineTo(x+6,10+j*3);c.stroke();}c.restore();return true;};})();
